import numpy as np
from itertools import combinations

def add_interactions(X):
    X = np.asarray(X, dtype=float)
    new = [X[:, i] * X[:, j] for i, j in combinations(range(X.shape[1]), 2)]
    return np.column_stack([X] + new)

